questionvariables.text:
/* Possible cosine values */
cos_values : [
    [3/5, 4/5],
    [4/5, 3/5],
    [5/13, 12/13],
    [12/13, 5/13]
];

/* Select a random cosine/reference pair */
variant : rand(cos_values);

cos_abs : variant[1];
sin_abs : variant[2];

/* Randomly select a quadrant: II or III */
quadrant : rand([2,3]);

/* Determine the signs */
if quadrant = 2 then (
    cos_value : -cos_abs,
    sin_value : sin_abs
) else (
    cos_value : -cos_abs,
    sin_value : -sin_abs
);

/* Correct answer */
ta : sin_value;

/* Student mistake 1:
   correct magnitude but wrong sign */
ta_mistake1 : -sin_value;

/* Student mistake 2:
   uses the cosine magnitude as the sine value */
ta_mistake2 : cos_abs;
